{
  "technical_and_design_decisions": [
    "Capabilities framework will be implemented as described: three separate capability maps (channel, application, orderer) in channel config, with a single V1.1 capability per map for versioning.",
    "Binaries that do not support required capabilities will crash immediately to ensure data integrity.",
    "For the Read-Your-Writes feature, a new API method GetTrxState(key string) will be added to the chaincode stub interface.",
    "Performance metrics for CouchDB queries will be exposed using the existing Prometheus metrics infrastructure.",
    "MSPConfig will be refactored from a struct to an interface to allow custom implementations outside configtxgen.",
    "Chaincode singletons will be removed and replaced with dependency injection to improve testability.",
    "Config file generation for peer and orderer from World config will be implemented as a helper in the test framework.",
    "The new lifecycle validation interface will return validation parameters including a special auto-generated policy for '+lifecycle'."
  ],
  "assumptions": [
    "The development environment is set up with Go 1.10+ and Hyperledger Fabric source code at version 1.0.",
    "All necessary dependencies (e.g., protobuf, crypto libraries) are already available.",
    "The team has prior experience with Hyperledger Fabric architecture and Go programming.",
    "Testing includes unit tests, integration tests, and code review as part of development effort.",
    "No external dependencies or third-party tools beyond standard Hyperledger Fabric dependencies are required.",
    "The video for adding organizations (U3) will be created using standard screen recording/editing software and will be approximately 10-15 minutes long.",
    "Workdays are 8-hour productive days without overhead from meetings or other non-development tasks."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Capabilities Framework - Core Implementation",
      "activity_description": "Design and implement the capabilities framework core: define capability interfaces in fabric/common/channelconfig/api.go, add capability maps to channel configuration proto, implement parsing and storage of capabilities, create versioned capability strings for V1.1 in fabric/common/capabilities/<component>.go, and wire capability checks into config processing.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A2",
      "activity_name": "Capabilities Framework - Validation & Crash Behavior",
      "activity_description": "Implement validation logic that crashes the binary if a required capability is not supported. Add enforcement during channel config update (orderer prevents enabling application capabilities before orderer capabilities). Implement the crash mechanism for peers and orderers when unsupported capabilities are detected.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "Capabilities Framework - Integration & Tests",
      "activity_description": "Integrate capabilities framework with the existing channel configuration code, including upgrade scenario handling. Write unit tests for capability interfaces, integration tests for config updates with capabilities, and end-to-end tests for the upgrade process. Ensure all tests pass.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Read-Your-Writes (RYW) API Extension",
      "activity_description": "Add GetTrxState(key string) method to the chaincode stub interface (shim) that allows chaincode to read its own uncommitted writes. Implement the method by accessing the transaction's write set. Update documentation and add unit tests for the new API.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5",
      "activity_name": "Video: Adding Organizations to a Running Network",
      "activity_description": "Create a screen-cast video demonstrating how to add additional organizations to a running Fabric network without bringing it down. Include a high-level diagram, step-by-step configuration commands, and verification steps. Produce and finalize the video.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "CouchDB Query Performance Metrics",
      "activity_description": "Add instrumentation to CouchDB state database queries to expose performance metrics (e.g., query latency, number of queries, errors). Integrate with the existing Prometheus metrics endpoint in the peer. Add tests for the metrics.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Refactor MSPConfig to Interface",
      "activity_description": "Change MSPConfig from a concrete struct to an interface to allow custom implementations. Update all usages in configtxgen, channel config, and test code. Ensure backward compatibility where possible.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A8",
      "activity_name": "Remove Chaincode Singletons",
      "activity_description": "Refactor the chaincode lifecycle and runtime code to eliminate singleton patterns (e.g., global state in chaincode support). Replace with dependency injection and proper object instantiation. Update affected tests to use mocks.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A9",
      "activity_name": "Generate Config Files from World Config",
      "activity_description": "Implement a utility or test helper that generates peer core.yaml and orderer.yaml configuration files based on values set in the World config (test network configuration). Ensure the generated files are valid and can be used directly.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "Lifecycle Validation Interface Implementation",
      "activity_description": "Implement the interface that returns validation parameters for a chaincode in the new lifecycle. Handle the special case for '+lifecycle' by generating an automatic signature policy requiring majority of orgs. Support future channel config policy evaluation. Write unit and integration tests.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 44
  }
}

